function Chart({points,reference,expiryMs}:{points:Point[];reference?:number;expiryMs?:number}){
  const ordered=points.filter(p=>Number.isFinite(p.at)).sort((a,b)=>a.at-b.at);
  const valid=ordered.filter((p):p is Point&{price:number}=>!p.gap&&typeof p.price==="number"&&Number.isFinite(p.price));
  if(!valid.length)return <div className="chart-empty">Waiting for fresh comparison points. No price history is being invented.</div>;
  const values=valid.map(p=>p.price), low=Math.min(...values,reference??Infinity),high=Math.max(...values,reference??-Infinity);
  const padding=Math.max(.5,(high-low)*.15),bottom=low-padding,top=high+padding;
  const start=Math.max(valid[0].at,valid[valid.length-1].at-5*60_000),end=Math.max(valid[valid.length-1].at+10_000,expiryMs&&expiryMs>valid[valid.length-1].at?expiryMs+8_000:0);
  const x=(at:number)=>((at-start)/(end-start))*1000;
  const y=(price:number)=>300-(price-bottom)/(top-bottom)*300;
  const segments:(Point&{price:number})[][]=[],gapMarks:number[]=[];
  let current:(Point&{price:number})[]=[];
  const finishSegment=()=>{if(current.length)segments.push(current);current=[]};
  for(const sample of ordered){
    if(sample.gap||sample.price==null||!Number.isFinite(sample.price)){
      finishSegment();
      gapMarks.push(sample.at);
      continue;
    }
    const point=sample as Point&{price:number},previous=current.at(-1);
    if(previous&&point.at-previous.at>30_000){
      gapMarks.push(previous.at+(point.at-previous.at)/2);
      finishSegment();
    }
    current.push(point);
  }
  finishSegment();
  const last=valid[valid.length-1],refY=reference==null?null:y(reference),expiryX=expiryMs!=null&&expiryMs>=start&&expiryMs<=end?x(expiryMs):null;
  return <div className="chart-box">
    <svg className="chart" viewBox="0 0 1000 300" preserveAspectRatio="none" role="img"
       aria-label={`Coinbase comparison—not settlement oracle; comparison price history through ${time(last.at)} UTC`}>
      <defs><linearGradient id="comparison-fill" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#2c9eff" stopOpacity=".23"/><stop offset="1" stopColor="#2c9eff" stopOpacity="0"/></linearGradient></defs>
      {refY!==null&&<line x1="0" y1={refY} x2="1000" y2={refY} stroke="#9aaeba" strokeDasharray="5 5" strokeWidth="1" vectorEffect="non-scaling-stroke"/>}
      {expiryX!==null&&<line x1={expiryX} y1="0" x2={expiryX} y2="300" stroke="#d6a955" strokeDasharray="3 5" strokeWidth="1" vectorEffect="non-scaling-stroke"/>}
      {gapMarks.map((at,i)=><line key={`gap-${i}`} x1={x(at)} y1="0" x2={x(at)} y2="300" stroke="#687783" strokeDasharray="2 7" strokeWidth="1" opacity=".6" vectorEffect="non-scaling-stroke"/>)}
      {segments.map((segment,i)=>{
        const path=segment.map((p,j)=>`${j?"L":"M"} ${x(p.at)} ${y(p.price!)}`).join(" ");
        return <g key={i}>{segment.length>1&&<path d={`${path} L ${x(segment.at(-1)!.at)} 300 L ${x(segment[0].at)} 300 Z`} fill="url(#comparison-fill)"/>}
          <path d={path} fill="none" stroke="#39a6ff" strokeWidth="2" vectorEffect="non-scaling-stroke"/>
          {segment.length===1&&<circle cx={x(segment[0].at)} cy={y(segment[0].price)} r="2.2" fill="#68beff"/>}</g>;
      })}
      <circle cx={x(last.at)} cy={y(last.price)} r="7" fill="#39a6ff" opacity=".2"/>
      <circle cx={x(last.at)} cy={y(last.price)} r="3.2" fill="#68beff"/>
    </svg>
    <div className="chart-ticks"><span>{time(valid[0].at)} UTC</span><span>Last observed {money(last.price)} · {time(last.at)} UTC</span></div>
     <div className="chart-legend"><span><i className="line-blue"/> Coinbase comparison</span><span className="legend-settlement"><i className="line-settlement"/> Settlement oracle · not plotted</span>
       {refY!==null&&<span className="legend-reference"><i className="line-dash"/> Round reference</span>}
      {expiryX!==null&&<span className="legend-expiry"><i className="line-expiry"/> Round expiry</span>}
      {!!gapMarks.length&&<span className="legend-gap"><i className="line-gap"/> Gaps retained · no line drawn</span>}</div>
     <details className="chart-provenance"><summary>Feed timestamps &amp; provenance</summary><div className="provider-stamp">Provider observation {last.sourceAt==null?"timestamp not reported":`${time(last.sourceAt)} UTC`} · age {last.sourceAgeMs==null?"not reported":`${(last.sourceAgeMs/1000).toFixed(1)}s`}</div></details>
  </div>;
}
function pointFeedState(points:Point[],now:number){
  const ordered=points.filter(p=>Number.isFinite(p.at)).sort((a,b)=>a.at-b.at),tail=ordered.at(-1);
  const lastPrice=[...ordered].reverse().find(p=>!p.gap&&typeof p.price==="number"&&Number.isFinite(p.price));
  if(!lastPrice)return {label:"AWAITING DATA",tone:"awaiting" as const};
  if(tail?.gap||tail?.price==null)return {label:"FEED PAUSED · GAP",tone:"paused" as const};
  const timestampMs=lastPrice.sourceAt==null?NaN:typeof lastPrice.sourceAt==="number"?lastPrice.sourceAt:Date.parse(lastPrice.sourceAt);
  const timestampAge=Number.isFinite(timestampMs)?Math.max(0,now-timestampMs):null;
  if(lastPrice.sourceAgeMs==null&&timestampAge==null)return {label:"AGE UNVERIFIED",tone:"stale" as const};
  const staleMs=Math.max(lastPrice.sourceAgeMs??0,timestampAge??0);
  if(staleMs>30_000)return {label:`STALE · ${Math.floor(staleMs/1000)}s`,tone:"stale" as const};
  return {label:`LIVE TRACE · ${(staleMs/1000).toFixed(1)}s`,tone:"fresh" as const};
}
