const accuracyRate=(value?:number|null)=>value==null||!Number.isFinite(value)||value<0||value>1?"Unavailable":`${(value*100).toFixed(1)}%`;
const accuracyScore=(value?:number|null,kind:"brier"|"logLoss"="logLoss")=>value==null||!Number.isFinite(value)||value<0||(kind==="brier"&&value>1)?"Unavailable":value.toFixed(4);
function AccuracyMetricRow({label,count,metrics,unavailableReason}:{label:string;count?:number;metrics?:AccuracyMetrics|null;unavailableReason?:string|null}){
  const values=metrics;
  const hasAny=!!values&&[values.hitRate,values.brier,values.logLoss,values.coverage].some(v=>typeof v==="number"&&Number.isFinite(v));
  return <div className="accuracy-metric-row"><div className="accuracy-row-label"><strong>{label}</strong><span>n={count??"—"}{unavailableReason?` · ${unavailableReason}`:!hasAny?" · Unavailable":""}</span></div><span>{accuracyRate(values?.hitRate)}</span><span>{accuracyScore(values?.brier,"brier")}</span><span>{accuracyScore(values?.logLoss,"logLoss")}</span><span>{accuracyRate(values?.coverage)}</span></div>
}
function AccuracyExports(){
  const [collection,setCollection]=useState<"predictions"|"outcomes"|"scores">("predictions"),[jsonPage,setJsonPage]=useState(""),[nextCursor,setNextCursor]=useState<string|null>(null),[loading,setLoading]=useState(false),[error,setError]=useState("");
  const exportUrl=(kind:string,format:"csv"|"json",cursor?:string)=>`/api/accuracy/export?collection=${kind}&format=${format}&limit=100${cursor?`&cursor=${encodeURIComponent(cursor)}`:""}`;
  const fetchJsonPage=async(cursor?:string)=>{setLoading(true);setError("");try{const response=await fetch(exportUrl(collection,"json",cursor));if(!response.ok)throw new Error(`Export request failed (${response.status})`);const body=await response.json();setJsonPage(JSON.stringify(body,null,2));setNextCursor(response.headers.get("X-Next-Cursor"));}catch(e){setError(e instanceof Error?e.message:"Unable to load export page");setJsonPage("")}finally{setLoading(false)}};
  return <div className="accuracy-exports"><div className="accuracy-export-links"><span>CSV exports</span>{(["predictions","outcomes","scores"] as const).map(kind=><a className="button" key={kind} href={exportUrl(kind,"csv")} download>{kind}</a>)}</div><div className="accuracy-cursor-tools"><label className="field">JSON collection<select className="select" value={collection} disabled={loading} onChange={e=>{setCollection(e.target.value as typeof collection);setJsonPage("");setNextCursor(null);setError("")}}><option value="predictions">Predictions</option><option value="outcomes">Outcomes</option><option value="scores">Scores</option></select></label><button className="button" onClick={()=>fetchJsonPage()} disabled={loading}>{loading?"Loading page…":"Load JSON page"}</button>{nextCursor&&<button className="button" onClick={()=>fetchJsonPage(nextCursor)} disabled={loading}>Next page</button>}</div><p className="accuracy-cursor-note">CSV and JSON requests are capped at 100 rows. JSON pagination reads <code>X-Next-Cursor</code> and uses it for the next page.</p>{error&&<p className="accuracy-export-error" role="alert">{error}</p>}{jsonPage&&<details className="accuracy-json"><summary>JSON response page</summary><pre>{jsonPage}</pre></details>}</div>
}
